export default function PlayersList() {
  const [players] = useState(ALL_PLAYERS_DATABASE);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedSeason, setSelectedSeason] = useState('all');

  const filteredPlayers = players.filter(p => 
    p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.team.toLowerCase().includes(searchTerm.toLowerCase()) ||
    p.role.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="max-w-[1600px] mx-auto px-4 py-8 space-y-8 pb-16 font-sans">
      
      {/* Header & Controls */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
            <Users className="text-blue-600" size={32} /> Player Directory
          </h1>
          <p className="text-slate-500 text-sm mt-1">Comprehensive IPL player database with verified statistics and career records</p>
        </div>

        <div className="flex flex-col sm:flex-row items-center gap-3 w-full md:w-auto">
          {/* Season Filter Dropdown */}
          <div className="relative w-full sm:w-48">
            <select
              value={selectedSeason}
              onChange={(e) => setSelectedSeason(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm font-bold text-slate-800 shadow-sm focus:outline-none focus:ring-2 focus:ring-blue-500 cursor-pointer"
            >
              <option value="all">All Seasons</option>
              <option value="2026">2026 Season</option>
              <option value="2025">2025 Season</option>
              <option value="2024">2024 Season</option>
              <option value="2023">2023 Season</option>
              <option value="2022">2022 Season</option>
            </select>
          </div>

          {/* Search Bar */}
          <div className="relative w-full sm:w-80">
            <Search className="absolute left-3.5 top-3 text-slate-400" size={18} />
            <input
              type="text"
              placeholder="Search player, role, or team..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 text-sm font-semibold focus:outline-none focus:ring-2 focus:ring-blue-500 shadow-sm"
            />
          </div>
        </div>
      </div>

      {/* Analytics Data Table */}
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="overflow-x-auto max-h-[750px]">
          <table className="w-full text-left border-collapse whitespace-nowrap">
            <thead className="sticky top-0 bg-slate-50 z-10">
              <tr className="border-b border-slate-200 text-xs font-black text-slate-400 uppercase tracking-wider">
                <th className="py-4 px-6">Player</th>
                <th className="py-4 px-4 text-center">Role</th>
                <th className="py-4 px-4 text-center">Team</th>
                <th className="py-4 px-4 text-center">Mat</th>
                <th className="py-4 px-4 text-center">Runs</th>
                <th className="py-4 px-4 text-center">Avg</th>
                <th className="py-4 px-4 text-center">SR</th>
                <th className="py-4 px-4 text-center">Wkts</th>
                <th className="py-4 px-4 text-center">Econ</th>
                <th className="py-4 px-6 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100 text-sm font-semibold text-slate-800">
              {filteredPlayers.length > 0 ? (
                filteredPlayers.map((player, index) => (
                  <tr key={player.id} className="hover:bg-slate-50 transition-colors group">
                    <td className="py-4 px-6 flex items-center gap-3">
                      <span className="w-6 text-xs font-bold text-slate-400">{index + 1}</span>
                      <div className="w-9 h-9 bg-blue-50 text-blue-600 rounded-full flex items-center justify-center font-black text-sm flex-shrink-0 shadow-sm">
                        {player.name[0]}
                      </div>
                      <span className="font-extrabold text-slate-900 group-hover:text-blue-600 transition-colors">
                        {player.name}
                      </span>
                    </td>
                    <td className="py-4 px-4 text-center">
                      <span className="inline-block bg-slate-100 text-slate-600 text-xs font-bold px-2.5 py-1 rounded-md">
                        {player.role}
                      </span>
                    </td>
                    <td className="py-4 px-4 text-center">
                      <span className="inline-block bg-blue-50 text-blue-700 text-xs font-extrabold px-2.5 py-1 rounded-md">
                        {player.team}
                      </span>
                    </td>
                    <td className="py-4 px-4 text-center font-mono text-slate-600">{player.matches}</td>
                    <td className="py-4 px-4 text-center font-mono font-black text-slate-900">{player.runs}</td>
                    <td className="py-4 px-4 text-center font-mono text-slate-700">{player.avg}</td>
                    <td className="py-4 px-4 text-center font-mono text-slate-700">{player.sr}</td>
                    <td className="py-4 px-4 text-center font-mono font-black text-purple-600">{player.wickets}</td>
                    <td className="py-4 px-4 text-center font-mono text-slate-700">{player.economy}</td>
                    <td className="py-4 px-6 text-right">
                      <Link
                        to={`/player/${encodeURIComponent(player.name)}`}
                        className="inline-flex items-center gap-1 bg-slate-100 text-slate-700 hover:bg-blue-600 hover:text-white px-3.5 py-1.5 rounded-xl text-xs font-bold transition-all shadow-sm"
                      >
                        View Stats <ChevronRight size={14} />
                      </Link>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="10" className="text-center py-12 text-slate-400 font-bold">No players found matching your search criteria.</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}